tape( 'the sine is odd and the cosine is even', function test( t ) {
	var x;
	var y;
	var v;
	var i;

	x = decimals.x;
	for ( i = 0; i < x.length; i++ ) {
		y = sincospif( -x[ i ] );
		v = sincospif( x[ i ] );
		t.strictEqual( isSameValue( y[ 0 ], -v[ 0 ] ), true, 'returns expected value' );
		t.strictEqual( isSameValue( y[ 1 ], v[ 1 ] ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'if provided a value exceeding `2**24`, the function returns `[±0,1]`', function test( t ) {
	var x;
	var y;
	var i;

	x = powf( 2.0, 24 ) + 1.0;
	for ( i = 0; i < 100; i++ ) {
		y = sincospif( x + i );
		t.strictEqual( isPositiveZerof( y[ 0 ] ), true, 'returns expected value' );
		t.strictEqual( y[ 1 ], 1.0, 'returns expected value' );
		y = sincospif( -( x + i ) );
		t.strictEqual( isNegativeZerof( y[ 0 ] ), true, 'returns expected value' );
		t.strictEqual( y[ 1 ], 1.0, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes `sin(πx)` and `cos(πx)` for a fractional part equal to `1/2`', function test( t ) {
	var x;
	var y;
	var i;

	for ( i = -100; i <= 100; i++ ) {
		x = 0.5 + i;
		y = sincospif( x );
		t.strictEqual( y[ 0 ], ( (i%2 === 0) ? 1.0 : -1.0 ), 'returns expected value' );
		t.strictEqual( isPositiveZerof( y[ 1 ] ), true, 'returns expected value' );
	}
	t.end();
});
